":"FIB","prompt":"Complete the missing Java token in this fragment for Unlimited Stock Trades:\n\nprofit += Math.max(0, a[i] ___ a[i-1]);","expected":["-"],"options":[],"rubric":"Required Java token: -"},{"slug":"unlimited-stock-trades","ordinal":2,"kind":"MCQ","prompt":"What output should a correct solution produce for this input?\n\n6\n9 0 9 0 3 3\n","expected":["C"],"options":[{"id":"A","text":"13"},{"id":"B","text":"11"},{"id":"C","text":"12"},{"id":"D","text":"14"}],"rubric":"Apply the coding question specification. Expected output: 12"},{"slug":"unlimited-stock-trades","ordinal":3,"kind":"DRAG_DROP","prompt":"Complete the algorithm for Unlimited Stock Trades. Place the three pieces in execution order: [1], [2], [3].","expected":["A","B","C"],"options":[{"id":"A","text":"Compare each price with the preceding price"},{"id":"B","text":"Add only positive changes"},{"id":"C","text":"Return the accumulated profit"}],"rubric":"Correct order: Compare each price with the preceding price -> Add only positive changes -> Return the accumulated profit"},{"slug":"unlimited-stock-trades","ordinal":4,"kind":"DEBUG","prompt":"Replace this incorrect Java fragment with a corrected fragment. Keep the same variable names.\n\nprofit += a[i] - a[i-1];","expected":["profit += Math.max(0, a[i] - a[i-1]);"],"options":[],"rubric":"Suggested correction: profit += Math.max(0, a[i] - a[i-1]);. Equivalent corrections should be reviewed by staff."},{"slug":"unlimited-stock-trades","ordinal":5,"kind":"SHORT_ANSWER","prompt":"Why can adjacent positive changes be added with unlimited fee-free trades?","expected":[],"options":[],"rubric":"Each rising run can be captured as a single trade or adjacent trades with the same telescoping total; falling changes are avoided."},{"slug":"maximum-sortable-chunks","ordinal":1,"kind":"FIB","prompt":"Complete the missing Java token in this fragment for Maximum Sortable Chunks:\n\nif (frequencyDifference.is___()) chunks++;","expected":["Empty"],"options":[],"rubric":"Required Java token: Empty"},{"slug":"maximum-sortable-chunks","ordinal":2,"kind":"MCQ","prompt":"What output should a correct solution produce for this input?\n\n6\n-5 4 -2 4 -5 9\n","expected":["C"],"options":[{"id":"A","text":"5"},{"id":"B","text":"2"},{"id":"C","text":"3"},{"id":"D","text":"4"}],"rubric":"Apply the coding question specification. Expected output: 3"},{"slug":"maximum-sortable-chunks","ordinal":3,"kind":"DRAG_DROP","prompt":"Complete the algorithm for Maximum Sortable Chunks. Place the three pieces in execution order: [1], [2], [3].","expected":["C","A","B"],"options":[{"id":"A","text":"Track multiset differences between original and sorted prefixes"},{"id":"B","text":"End a chunk when the prefix difference is empty"},{"id":"C","text":"Create a sorted copy"}],"rubric":"Correct order: Create a sorted copy -> Track multiset differences between original and sorted prefixes -> End a chunk when the prefix difference is empty"},{"slug":"maximum-sortable-chunks","ordinal":4,"kind":"DEBUG","prompt":"Replace this incorrect Java fragment with a corrected fragment. Keep the same variable names.\n\nif (a[i] == sorted[i]) chunks++;","expected":["if (frequencyDifference.isEmpty()) chunks++;"],"options":[],"rubric":"Suggested correction: if (frequencyDifference.isEmpty()) chunks++;. Equivalent corrections should be reviewed by staff."},{"slug":"maximum-sortable-chunks","ordinal":5,"kind":"SHORT_ANSWER","prompt":"Why is comparing only the current pair of values insufficient?","expected":[],"options":[],"rubric":"A chunk boundary requires whole-prefix multisets to match, not merely one position."},{"slug":"shortest-unsorted-segment","ordinal":1,"kind":"FIB","prompt":"Complete the missing Java token in this fragment for Shortest Unsorted Segment:\n\nlength = right - left ___ 1;","expected":["+"],"options":[],"rubric":"Required Java token: +"},{"slug":"shortest-unsorted-segment","ordinal":2,"kind":"MCQ","prompt":"What output should a correct solution produce for this input?\n\n6\n-5 4 -2 4 -5 9\n","expected":["B"],"options":[{"id":"A","text":"3"},{"id":"B","text":"4"},{"id":"C","text":"6"},{"id":"D","text":"5"}],"rubric":"Apply the coding question specification. Expected output: 4"},{"slug":"shortest-unsorted-segment","ordinal":3,"kind":"DRAG_DROP","prompt":"Complete the algorithm for Shortest Unsorted Segment. Place the three pieces in execution order: [1], [2], [3].","expected":["B","C","A"],"options":[{"id":"A","text":"Measure the inclusive interval between the boundaries"},{"id":"B","text":"Locate values violating the running maximum from the left"},{"id":"C","text":"Locate values violating the running minimum from the right"}],"rubric":"Correct order: Locate values violating the running maximum from the left -> Locate values violating the running minimum from the right -> Measure the inclusive interval between the boundaries"},{"slug":"shortest-unsorted-segment","ordinal":4,"kind":"DEBUG","prompt":"Replace this incorrect Java fragment with a corrected fragment. Keep the same variable names.\n\nreturn right - left;","expected":["return right < 0 ? 0 : right - left + 1;"],"options":[],"rubric":"Suggested correction: return right < 0 ? 0 : right - left + 1;. Equivalent corrections should be reviewed by staff."},{"slug":"shortest-unsorted-segment","ordinal":5,"kind":"SHORT_ANSWER","prompt":"What should an already sorted array return?","expected":[],"options":[],"rubric":"Zero; no segment needs sorting."},{"slug":"shortest-degree-segment","ordinal":1,"kind":"FIB","prompt":"Complete the missing Java token in this fragment for Shortest Degree Segment:\n\nlength = lastIndex - firstIndex ___ 1;","expected":["+"],"options":[],"rubric":"Required Java token: +"},{"slug":"shortest-degree-segment","ordinal":2,"kind":"MCQ","prompt":"What output should a correct solution produce for this input?\n\n6\n-5 4 -2 4 -5 9\n","expected":["D"],"options":[{"id":"A","text":"4"},{"id":"B","text":"2"},{"id":"C","text":"5"},{"id":"D","text":"3"}],"rubric":"Apply the coding question specification. Expected output: 3"},{"slug":"shortest-degree-segment","ordinal":3,"kind":"DRAG_DROP","prompt":"Complete the algorithm for Shortest Degree Segment. Place the three pieces in execution order: [1], [2], [3].","expected":["A","B","C"],"options":[{"id":"A","text":"Count frequencies and track first and last positions"},{"id":"B","text":"Identify values achieving the whole-array degree"},{"id":"C","text":"Choose the shortest span among those values"}],"rubric":"Correct order: Count frequencies and track first and last positions -> Identify values achieving the whole-array degree -> Choose the shortest span among those values"},{"slug":"shortest-degree-segment","ordinal":4,"kind":"DEBUG","prompt":"Replace this incorrect Java fragment with a corrected fragment. Keep the same variable names.\n\nbest = Math.max(best, lastIndex - firstIndex + 1);","expected":["best = Math.min(best, lastIndex - firstIndex + 1);"],"options":[],"rubric":"Suggested correction: best = Math.min(best, lastIndex - firstIndex + 1);. Equivalent corrections should be reviewed by staff."},{"slug":"shortest-degree-segment","ordinal":5,"kind":"SHORT_ANSWER","prompt":"Why must a qualifying span include every occurrence of a degree-achieving value?","expected":[],"options":[],"rubric":"To retain that maximum frequency, all occurrences of at least one value with the global degree must be present."},{"slug":"nearby-equal-values","ordinal":1,"kind":"FIB","prompt":"Complete the missing Java token in this fragment for Nearby Equal Values:\n\nif (i - previous ___ k) return true;","expected":["<="],"options":[],"rubric":"Required Java token: <="},{"slug":"nearby-equal-values","ordinal":2,"kind":"MCQ","prompt":"What output should a correct solution produce for this input?\n\n6 49\n-5 4 -2 4 -5 9\n","expected":["C"],"options":[{"id":"A","text":"1"},{"id":"B","text":"-1"},{"id":"C","text":"true"},{"id":"D","text":"0"}],"rubric":"Apply the coding question specification. Expected output: true"},{"slug":"nearby-equal-values","ordinal":3,"kind":"DRAG_DROP","prompt":"Complete the algorithm for Nearby Equal Values. Place the three pieces in execution order: [1], [2], [3].","expected":["B","C","A"],"options":[{"id":"A","text":"Replace the saved index with the current index"},{"id":"B","text":"Track the most recent index for each value"},{"id":"C","text":"Compare the current gap against k"}],"rubric":"Correct order: Track the most recent index for each value -> Compare the current gap against k -> Replace the saved index with the current index"},{"slug":"nearby-equal-values","ordinal":4,"kind":"DEBUG","prompt":"Replace this incorrect Java fragment with a corrected fragment. Keep the same variable names.\n\nif (i - previous < k) return true;","expected":["if (i - previous <= k) return true;"],"options":[],"rubric":"Suggested correction: if (i - previous <= k) return true;. Equivalent corrections should be reviewed by staff."},{"slug":"nearby-equal-values","ordinal":5,"kind":"SHORT_ANSWER","prompt":"Why is keeping only the most recent occurrence enough?","expected":[],"options":[],"rubric":"It gives the smallest possible distance to an earlier equal value. Older occurrences cannot offer a smaller gap."}]$followups$::jsonb)
AS f(slug text,ordinal int,kind text,prompt text,options jsonb,expected jsonb,rubric text);
DO $$ BEGIN
 IF (SELECT count(*) FROM followup_seed f JOIN challenge_platform.question q USING(slug))<>100 THEN RAISE EXCEPTION 'Missing coding questions'; END IF;
END $$;
INSERT INTO challenge_platform.question_followup(question_id,ordinal,kind,prompt,options,expected_answer,rubric)
SELECT q.id,f.ordinal,f.kind,f.prompt,f.options,f.expected,f.rubric FROM followup_seed f JOIN challenge_platform.question q USING(slug)
ON CONFLICT(question_id,ordinal) DO NOTHING;
DO $$ BEGIN
 IF EXISTS(SELECT 1 FROM followup_seed f JOIN challenge_platform.question q USING(slug)
 JOIN challenge_platform.question_followup v ON v.question_id=q.id AND v.ordinal=f.ordinal
 WHERE (v.kind,v.prompt,v.options,v.expected_answer,v.rubric,v.enabled) IS DISTINCT FROM (f.kind,f.prompt,f.options,f.expected,f.rubric,true)) THEN
 RAISE EXCEPTION 'Existing follow-ups differ; refusing to overwrite'; END IF;
 IF (SELECT count(*) FROM challenge_platform.followup_eligible_question)<>20 THEN RAISE EXCEPTION 'Expected twenty eligible questions'; END IF;
END $$;
COMMIT;
